import http from 'node:http';

const RATES_URL = 'https://api.exchangerate.host/latest';
const CACHE_TTL_MS = 10 * 60 * 1000;
let cache = null; // { data, fetchedAt }

async function getRates() {
  const isFresh = cache && Date.now() - cache.fetchedAt < CACHE_TTL_MS;
  if (isFresh) return cache.data;

  try {
    const response = await fetch(RATES_URL);
    if (!response.ok) throw new Error(`Upstream returned ${response.status}`);
    const data = await response.json();
    cache = { data, fetchedAt: Date.now() };
    return cache.data;
  } catch (err) {
    if (cache) return cache.data; // serve stale data rather than fail
    throw err;
  }
}

const server = http.createServer(async (req, res) => {
  if (req.url === '/health') return res.end('ok');

  if (req.url === '/rates') {
    try {
      const data = await getRates();
      res.setHeader('Content-Type', 'application/json');
      return res.end(JSON.stringify(data));
    } catch (err) {
      res.statusCode = 502;
      res.setHeader('Content-Type', 'application/json');
      return res.end(JSON.stringify({ error: 'Failed to fetch exchange rates' }));
    }
  }

  res.statusCode = 404; res.end();
});
server.listen(process.env.PORT ?? 3000);

